export const GENERATION_REGIONS = [
  { gen: 1, region: "Kanto", range: "1–151", count: 151 },
  { gen: 2, region: "Johto", range: "152–251", count: 100 },
  { gen: 3, region: "Hoenn", range: "252–386", count: 135 },
  { gen: 4, region: "Sinnoh", range: "387–493", count: 107 },
  { gen: 5, region: "Unova", range: "494–649", count: 156 },
  { gen: 6, region: "Kalos", range: "650–721", count: 72 },
  { gen: 7, region: "Alola", range: "722–809", count: 88 },
  { gen: 8, region: "Galar", range: "810–905", count: 96 },
  { gen: 9, region: "Paldea", range: "906–1025", count: 120 },
];

export function getPokemonByIdOrSlug(idOrSlug: string | number): PokedexEntry | undefined {
  if (typeof idOrSlug === "number" || !isNaN(Number(idOrSlug))) {
    const num = Number(idOrSlug);
    return POKEDEX_DATA[num - 1];
  }
  const lower = String(idOrSlug).toLowerCase().trim();
  const directMatch = POKEDEX_DATA.find(
    (p) => p.slug === lower || p.name.toLowerCase() === lower
  );
  if (directMatch) return directMatch;

  // Fallback: match if slug or name is the prefix of a form query (e.g. "aegislash-shield" -> "aegislash")
  return POKEDEX_DATA.find(
    (p) => lower.startsWith(p.slug + "-") || lower.startsWith(p.name.toLowerCase() + " ")
  );
}

export function findPokemonForCardName(cardName: string): PokedexEntry | undefined {
  if (!cardName) return undefined;
  const raw = cardName.trim();
  if (/code card/i.test(raw)) return undefined;

  // 1. Strip card number suffixes and variant parentheticals
  let clean = raw.replace(/\s*-\s*\d+\/\d+.*$/, "");
  clean = clean.replace(/\s*\([^)]*\)/g, "").trim();

  // 2. Strip trainer/variant prefixes
  const prefixRegex = /^(dark|light|shining|radiant|rocket'?s|blaine'?s|erika'?s|brock'?s|misty'?s|giovanni'?s|sabrina'?s|koga'?s|lt\.?\s*surge'?s)\s+/i;
  const strippedPrefix = clean.replace(prefixRegex, "").trim();

  // 3. Strip mechanics suffixes
  const suffixRegex = /\s+(ex|gx|vmax|vstar|v-union|v|tag\s+team|prime|lv\.?\s*x|break|star|δ)$/i;
  const strippedSuffix = strippedPrefix.replace(suffixRegex, "").trim();

  // a) Exact match on cleaned name
  const match1 = POKEDEX_DATA.find(
    (p) => p.name.toLowerCase() === strippedSuffix.toLowerCase() || p.slug === strippedSuffix.toLowerCase()
  );
  if (match1) return match1;

  // b) Word-boundary match across all species (longest names checked first so Mewtwo precedes Mew)
  const sortedByLength = [...POKEDEX_DATA].sort((a, b) => b.name.length - a.name.length);
  return sortedByLength.find((p) => {
    const escaped = p.name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const pattern = new RegExp(`\\b${escaped}\\b`, "i");
    return pattern.test(clean);
  });
}

